def generate_procedural_fusion_sprite(name):
    """Dynamically generates a custom 4-line procedural ASCII art sprite for fusions."""
    key = str(name).lower()
    char_sum = sum(ord(c) for c in key)
    
    heads = [
        r"   (\__/)",
        r"  /\___/\\",
        r"   /\_/\ ",
        r"  /\   /\\",
        r"   ____  ",
        r"  OOOOOO ",
    ]
    faces = [
        r"  (o^.^)",
        r" (  o o  )",
        r" <  o o  >",
        r" /  O O  \\",
        r" |  o o  |",
        r" (  > <  )",
    ]
    bodies = [
        r" z(_(\")(\")",
        r" /   V   \\",
        r"  \\  ^  / ",
        r"  `-.____.-'",
        r"   OO__OO",
        r" /|  ---  |\\",
    ]
    
    # Select components based on hash indices
    h = heads[char_sum % len(heads)]
    f = faces[(char_sum // 3) % len(faces)]
    b = bodies[(char_sum // 7) % len(bodies)]
    
    # Determine elemental emojis based on the name characters
    emojis = ["🔥", "💧", "🌿", "⚡", "🪨", "🌀", "❄️", "✨", "👻", "🦖"]
    emoji = emojis[char_sum % len(emojis)]
    
    return f"""
{h}
{f}  {emoji}
{b}
  '{name.upper()}'
    """


def get_pokemon_sprite(name):
    key = str(name).lower()
    if key in POKEMON_SPRITES:
        return POKEMON_SPRITES[key]
    return generate_procedural_fusion_sprite(name)


